  if(name==='compass')return wrap(`<g class="pen-blue"><path d="M32 9c-29-1-31 44-2 46 30 3 34-44 2-46Zm0 4c-24-1-25 36-1 38 26 1 28-37 1-38Z"/><path d="m32 19-9 23 17-17-8-6m0 0 8 6-2 17-15 0"/></g><g class="pen-red"><path d="m33 3-1 8m0 42-1 8M3 32l8 1m42 0 8 1M31 21l-4 13 8-8-4-5"/></g>`,`Компас, нарисованный синей и красной ручкой`,'0 0 64 64');
  if(name==='flag')return wrap(`<g class="pen-blue"><path d="m6 52 22-37 29 37-51 1m14-25 9 5 6-6m-24 23 42-1"/></g><g class="pen-red"><path d="m28 15 1-11 14 4-13 5"/></g>`,'Гора с флажком','0 0 64 64');
  if(name==='keyboard')return wrap(`<g class="pen-blue"><path d="m8 18 48-1 3 29-53 1 2-29m3 4 41-1 2 21-44 1 1-21m1 7 41-1m-40 7 41-1m-39-13 1 14m6-14v14m7-14v14m7-14v14m7-14 1 14m7-14v14m-24 2 16-1"/></g><g class="pen-red"><path d="m8 51 45-1m-35 4 23-1"/></g>`,'Клавиатура, нарисованная цветной ручкой','0 0 64 64');
  if(name==='monitor')return wrap(`<g class="pen-blue"><path d="M8 9 56 8l1 33-49 1V9m5 4 38-1v24l-38 1V13m13 29-1 10m15-10 1 10M20 55l25-1"/><path d="m17 17 11-1m-11 5 18-1" opacity=".5"/></g><g class="pen-green"><path d="m23 29 7 4 13-12"/></g>`,'Монитор, нарисованный цветной ручкой','0 0 64 64');
  if(name==='mouse')return wrap(`<g class="pen-blue"><path d="M32 16C9 15 12 55 30 55c21 2 28-38 2-39Zm0 0 1-10q0-7 13-5M16 31l31-1m-15-13 1 13"/></g><g class="pen-red"><path d="M31 21v5m-10 13q-2 7 4 11"/></g>`,'Компьютерная мышь, нарисованная цветной ручкой','0 0 64 64');
  if(name==='backpack')return wrap(`<g class="pen-blue"><path d="M17 20q0-9 15-10 15 0 16 11l5 34-39 1 3-36m8-11V5q6-5 14 0v5M18 25l29-1m-28 11 27-1 1 15-29 1 1-15m1 6 25-1M14 22l-5 9 1 20 6 1m32-30 7 7-1 21-4 1"/></g><g class="pen-red"><path d="m29 24 1 5m0 11v5m-8-25 18-1"/></g>`,'Экспедиционный рюкзак, нарисованный ручкой','0 0 64 64');
  if(name==='camera')return wrap(`<g class="pen-blue"><path d="m8 21 13-1 4-8 15-1 5 8 11 1 1 31-49 1V21m24 4c-18-1-19 24-2 25 18 1 22-23 2-25Zm0 5c-12-1-13 15-1 16 12 1 14-15 1-16Z"/></g><g class="pen-red"><path d="m47 25 4-1v4h-4v-3m-19-7 10-1"/></g>`,'Фотоаппарат, нарисованный синей и красной ручкой','0 0 64 64');
  if(name==='tent')return wrap(`<g class="pen-blue"><path d="m10 53 25-41 24 40-49 1m25-41-1 41m1-34-16 33m16-33 15 32M6 57l55-1"/><path d="m36 12 11-6 14 40-2 6M47 6l-13 6"/></g><g class="pen-red"><path d="M10 53 3 57m56-5 4 4m-45-9 8-14m-3 17 5-10"/></g>`,'Палатка, нарисованная цветными ручками','0 0 64 64');
  if(name==='shield')return wrap(`<g class="pen-green"><path d="M32 6 54 15l-3 26q-5 13-20 18Q12 50 12 40L9 16 32 6Zm0 5-18 8 2 21q4 10 15 14 15-7 16-15l2-21-17-7Z"/></g><g class="pen-blue"><path d="m22 31 8 8 14-19m-22 12 7 8 15-19"/></g>`,'Защитный щит с галочкой, нарисованный ручкой','0 0 64 64');
  if(name==='cpu')return wrap(`<g class="pen-blue"><path d="m17 16 30-1 1 32-31 1V16m6 6 18-1 1 19-19 1V22M11 22h6m-6 9h6m-6 9h6m31-18h6m-6 9h6m-6 9h6M23 9v7m9-7v7m8-7v6M23 48v7m9-7v7m8-7v7"/></g><g class="pen-red"><path d="m27 27 10-1 1 9-11 1v-9"/></g>`,'Процессор, нарисованный цветными ручками','0 0 64 64');
